mapper.sql:
LEFT JOIN ( SELECT u.channel_id, COUNT(DISTINCT u.template_id) AS template_count, COUNT(DISTINCT u.rule_id) AS affected_rule_count, COUNT(DISTINCT CASE WHEN u.rule_enabled = 1 THEN u.rule_id END) AS enabled_affected_rule_count FROM (
SELECT b.channel_id, NULL AS template_id, r.id AS rule_id, r.enabled AS rule_enabled FROM alarm_channel_binding b INNER JOIN alarm_rule_v2 r ON r.id = b.owner_id AND r.template_item_id IS NULL WHERE b.owner_type = 'RULE' UNION ALL SELECT b.channel_id, t.id AS template_id, r.id AS rule_id, r.enabled AS rule_enabled FROM alarm_channel_binding b INNER JOIN alarm_template t ON t.id = b.owner_id AND t.deleted = 0 LEFT JOIN alarm_template_item i ON i.template_id = t.id AND i.deleted = 0 LEFT JOIN alarm_rule_v2 r ON r.template_item_id = i.id WHERE b.owner_type = 'TEMPLATE'
) u GROUP BY u.channel_id ) usage_counts ON usage_counts.channel_id = c.id

LEFT JOIN ( SELECT u.channel_id, COUNT(DISTINCT u.template_id) AS template_count, COUNT(DISTINCT u.rule_id) AS affected_rule_count, COUNT(DISTINCT CASE WHEN u.rule_enabled = 1 THEN u.rule_id END) AS enabled_affected_rule_count FROM (
SELECT b.channel_id, NULL AS template_id, r.id AS rule_id, r.enabled AS rule_enabled FROM alarm_notification_channel fc INNER JOIN alarm_channel_binding b ON b.channel_id = fc.id INNER JOIN alarm_rule_v2 r ON r.id = b.owner_id AND r.template_item_id IS NULL WHERE b.owner_type = 'RULE' AND fc.service_name = #{serviceName} UNION ALL SELECT b.channel_id, t.id AS template_id, r.id AS rule_id, r.enabled AS rule_enabled FROM alarm_notification_channel fc INNER JOIN alarm_channel_binding b ON b.channel_id = fc.id INNER JOIN alarm_template t ON t.id = b.owner_id AND t.deleted = 0 LEFT JOIN alarm_template_item i ON i.template_id = t.id AND i.deleted = 0 LEFT JOIN alarm_rule_v2 r ON r.template_item_id = i.id WHERE b.owner_type = 'TEMPLATE' AND fc.service_name = #{serviceName}
) u GROUP BY u.channel_id ) usage_counts ON usage_counts.channel_id = c.id

LEFT JOIN ( SELECT u.channel_id, COUNT(DISTINCT u.template_id) AS template_count, COUNT(DISTINCT u.rule_id) AS affected_rule_count, COUNT(DISTINCT CASE WHEN u.rule_enabled = 1 THEN u.rule_id END) AS enabled_affected_rule_count FROM (
SELECT b.channel_id, NULL AS template_id, r.id AS rule_id, r.enabled AS rule_enabled FROM alarm_channel_binding b INNER JOIN alarm_rule_v2 r ON r.id = b.owner_id AND r.template_item_id IS NULL WHERE b.owner_type = 'RULE' AND b.channel_id = #{id} UNION ALL SELECT b.channel_id, t.id AS template_id, r.id AS rule_id, r.enabled AS rule_enabled FROM alarm_channel_binding b INNER JOIN alarm_template t ON t.id = b.owner_id AND t.deleted = 0 LEFT JOIN alarm_template_item i ON i.template_id = t.id AND i.deleted = 0 LEFT JOIN alarm_rule_v2 r ON r.template_item_id = i.id WHERE b.owner_type = 'TEMPLATE' AND b.channel_id = #{id}
) u GROUP BY u.channel_id ) usage_counts ON usage_counts.channel_id = c.id

LEFT JOIN ( SELECT u.channel_id, COUNT(DISTINCT u.template_id) AS template_count, COUNT(DISTINCT u.rule_id) AS affected_rule_count, COUNT(DISTINCT CASE WHEN u.rule_enabled = 1 THEN u.rule_id END) AS enabled_affected_rule_count FROM (
SELECT b.channel_id, NULL AS template_id, r.id AS rule_id, r.enabled AS rule_enabled FROM alarm_channel_binding b INNER JOIN alarm_rule_v2 r ON r.id = b.owner_id AND r.template_item_id IS NULL WHERE b.owner_type = 'RULE' AND b.channel_id IN
#{id}
UNION ALL SELECT b.channel_id, t.id AS template_id, r.id AS rule_id, r.enabled AS rule_enabled FROM alarm_channel_binding b INNER JOIN alarm_template t ON t.id = b.owner_id AND t.deleted = 0 LEFT JOIN alarm_template_item i ON i.template_id = t.id AND i.deleted = 0 LEFT JOIN alarm_rule_v2 r ON r.template_item_id = i.id WHERE b.owner_type = 'TEMPLATE' AND b.channel_id IN
#{id}
) u GROUP BY u.channel_id ) usage_counts ON usage_counts.channel_id = c.id

mapper.update:
UPDATE alarm_notification_channel
SET channel_name = #{channelName},
    method_type = #{methodType},
    destination = #{destination},
    config = #{config}
WHERE id = #{id}

mapper.delete:
DELETE FROM alarm_notification_channel
WHERE method_type IN ('EMAIL', 'SMS')
  AND destination = #{userGroupId}

